changeSet.sql:
if exists(select * from INFORMATION_SCHEMA.TABLES where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'CompanyHelpResource')
begin 
	exec sp_rename 'dbo.CompanyHelpResource', 'CompanyHelpResource_backup';
end

changeSet.rollback:
if exists(select * from INFORMATION_SCHEMA.TABLES where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'CompanyHelpResource_backup')
begin 
 	exec sp_rename 'dbo.CompanyHelpResource_backup', 'CompanyHelpResource';
end

